draw:
function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);
  ctx.strokeStyle = 'black';
  ctx.lineWidth = 4;
  ctx.beginPath();
  ctx.arc(W/2, H/2, 20, 0, 2 * Math.PI);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2, H/2 + 25);
  ctx.lineTo(W/2, H/2 + 50 + 10 * Math.sin(t));
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2 - 25, H/2 + 50);
  ctx.lineTo(W/2 - 25 + 10 * Math.sin(t), H/2 + 70);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2 + 25, H/2 + 50);
  ctx.lineTo(W/2 + 25 - 10 * Math.sin(t), H/2 + 70);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2 - 15, H/2 - 10);
  ctx.lineTo(W/2 - 30, H/2 - 20 + 5 * Math.sin(t));
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2 + 15, H/2 - 10);
  ctx.lineTo(W/2 + 30, H/2 - 20 - 5 * Math.sin(t));
  ctx.stroke();
  ctx.fillStyle = 'black';
  ctx.font = '24px Arial';
  ctx.textAlign = 'center';
  ctx.textBaseline = 'middle';
  ctx.fillText('HA', W/2 + 5 * Math.sin(2 * t), H/2 - 40 + 10 * Math.sin(t));
  ctx.restore();
}
